/** an unknown or empty name draws this (a neutral dot in a ring) */
export const FALLBACK_ICON = 'circle-dot'
/** the names the AI is shown, sorted (the other names in ALIASES are accepted too, not listed) */
export const ICON_NAMES: readonly string[] = Object.freeze(Object.keys(ICONS).sort())

/** a name as an AI may write it ("Shopping Bag", "shopping_bag", "ShoppingBag") in Lucide's kebab case */
const kebab = (name: string) => name.trim().replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase().replace(/[\s_]+/g, '-')

/** the icon in ICONS a name stands for (itself, or the icon it is another name of), or null */
export function resolveIcon(name: string | undefined): string | null {
  if (!name) return null
  for (const n of [name, kebab(name)]) {
    if (Object.hasOwn(ICONS, n)) return n
    if (Object.hasOwn(ALIASES, n)) return ALIASES[n]
  }
  return null
}
export function knownIcon(name: string): boolean {
  return resolveIcon(name) !== null
}
/** the icon's path data in the 24 grid, one string per element; an unknown or empty name gives the fallback's */
export function iconPaths(name: string | undefined): string[] {
  return [...ICONS[resolveIcon(name) ?? FALLBACK_ICON]]
}

const TOKEN = /[MLCZ]|[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?/g
const px = (v: number) => { const r = Math.round(v * 100) / 100; return r === 0 ? '0' : String(r) }
/** Path data of absolute M, L, C and Z (the display list's form) scaled by k about the origin and moved by (dx, dy),
 * numbers to 2 decimals. Anything else in `d` is an error. */
export function transformPath(d: string, k: number, dx: number, dy: number): string {
  if (d.replace(TOKEN, '').replace(/[\s,]+/g, '') !== '') throw new Error('transformPath: only absolute M, L, C and Z')
  let axis = 0
  return (d.match(TOKEN) ?? []).map((t) => {
    if (t === 'M' || t === 'L' || t === 'C' || t === 'Z') { axis = 0; return t }
    const v = Number(t) * k + (axis === 0 ? dx : dy)
    axis ^= 1
    return px(v)
  }).join(' ')
}

/** An icon drawn into the size × size box at (x, y) in slide px: one stroked path per element (no fill), round caps
 * and joins, the stroke `stroke24` in grid units (1.5 at 48 px is 3 px), all in one group (one editable group in the
 * PowerPoint file; by default `icon-<name>-<x>-<y>`). An unknown or empty name draws the fallback. */
export function iconItems(name: string | undefined, x: number, y: number, size: number, color: string, stroke24 = 1.5, group?: string): PathItem[] {
  const icon = resolveIcon(name) ?? FALLBACK_ICON
  const k = size / 24, g = group ?? `icon-${icon}-${Math.round(x)}-${Math.round(y)}`
  return ICONS[icon].map((d): PathItem => ({
    t: 'path', d: transformPath(d, k, x, y), stroke: { color, width: stroke24 * k, cap: 'round', join: 'round' }, group: g, role: 'icon',
  }))
}
